const CAT_META = {
  "Alkali Metal": {css:"--c-alkali", short:"Alkali"},
  "Alkaline Earth Metal": {css:"--c-alkaline", short:"Alkaline Earth"},
  "Transition Metal": {css:"--c-transition", short:"Transition"},
  "Post-Transition Metal": {css:"--c-posttrans", short:"Post-Transition"},
  "Metalloid": {css:"--c-metalloid", short:"Metalloid"},
  "Nonmetal": {css:"--c-nonmetal", short:"Nonmetal"},
  "Halogen": {css:"--c-halogen", short:"Halogen"},
  "Noble Gas": {css:"--c-noble", short:"Noble Gas"},
  "Lanthanide": {css:"--c-lanth", short:"Lanthanide"},
  "Actinide": {css:"--c-actin", short:"Actinide"},
};
const byZ = {}; ELEMENTS.forEach(e=>byZ[e.Z]=e);

//THEME
const themeToggle = document.getElementById('themeToggle');
const themeIcon = document.getElementById('themeIcon');
function setTheme(t){
  document.body.setAttribute('data-theme', t);
  localStorage.setItem('px-theme', t);
  themeIcon.innerHTML = t==='dark'
    ? '<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>'
    : '<path d="M12 3a6 6 0 0 0 9 9 9 9 0 1 1-9-9Z"/>';
}
setTheme(localStorage.getItem('px-theme') || (matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'));
themeToggle.addEventListener('click', ()=> setTheme(document.body.getAttribute('data-theme')==='dark' ? 'light':'dark'));

// MOBILE NAV
const hamburgerBtn = document.getElementById('hamburgerBtn');
const mobileNav = document.getElementById('mobileNav');
hamburgerBtn.addEventListener('click', ()=>{
  const open = mobileNav.classList.toggle('open');
  hamburgerBtn.setAttribute('aria-expanded', open);
});
mobileNav.querySelectorAll('a').forEach(a=>a.addEventListener('click', ()=>mobileNav.classList.remove('open')));

//BUILD TABLE
const ptable = document.getElementById('ptable');
const placeholders = [
  {col:3, row:6, label:"57–71\nLanthanides"},
  {col:3, row:7, label:"89–103\nActinides"},
];
function buildTable(){
  ptable.innerHTML = '';
  ELEMENTS.forEach(e=>{
    const meta = CAT_META[e.cat] || {css:'--c-unknown'};
    const btn = document.createElement('button');
    btn.className = 'elcell';
    btn.style.gridColumn = e.xpos;
    btn.style.gridRow = e.ypos;
    btn.style.setProperty('--cat', `var(${meta.css})`);
    btn.dataset.z = e.Z;
    btn.dataset.cat = e.cat;
    btn.dataset.phase = e.phase;
    btn.dataset.name = e.name.toLowerCase();
    btn.dataset.sym = e.sym.toLowerCase();
    btn.setAttribute('aria-label', `${e.name}, symbol ${e.sym}, atomic number ${e.Z}`);
    btn.innerHTML = `<span class="z">${e.Z}</span><span class="sym">${e.sym}</span><span class="ename">${e.name}</span><span class="mass">${e.mass}</span>`;
    btn.addEventListener('click', ()=>openPanel(e.Z));
    btn.addEventListener('mouseenter', ()=>updateReadout(e));
    btn.addEventListener('focus', ()=>updateReadout(e));
    ptable.appendChild(btn);
  });
  placeholders.forEach(p=>{
    const div = document.createElement('div');
    div.className='placeholder-cell';
    div.style.gridColumn = p.col; div.style.gridRow = p.row;
    div.innerText = p.label;
    ptable.appendChild(div);
  });
  const spacer = document.createElement('div');
  spacer.className='spacer-row'; spacer.style.gridRow = 8;
  ptable.appendChild(spacer);
}
buildTable();

