//FILTER CHIPS 
const catChips = document.getElementById('catChips');
const activeCats = new Set();
Object.entries(CAT_META).forEach(([name,m])=>{
  const chip = document.createElement('button');
  chip.className='filter-chip'; chip.type='button'; chip.setAttribute('aria-pressed','false');
  chip.style.setProperty('--dot', `var(${m.css})`);
  chip.innerHTML = `<span class="dot"></span>${m.short}`;
  chip.addEventListener('click', ()=>{
    const pressed = chip.getAttribute('aria-pressed')==='true';
    chip.setAttribute('aria-pressed', String(!pressed));
    if(pressed) activeCats.delete(name); else activeCats.add(name);
    applyFilters();
  });
  catChips.appendChild(chip);
});
const phaseChips = document.getElementById('phaseChips');
const activePhases = new Set();
['Solid','Liquid','Gas'].forEach(ph=>{
  const chip = document.createElement('button');
  chip.className='filter-chip'; chip.type='button'; chip.setAttribute('aria-pressed','false');
  chip.style.setProperty('--dot', 'var(--accent-2)');
  chip.textContent = ph;
  chip.addEventListener('click', ()=>{
    const pressed = chip.getAttribute('aria-pressed')==='true';
    chip.setAttribute('aria-pressed', String(!pressed));
    if(pressed) activePhases.delete(ph); else activePhases.add(ph);
    applyFilters();
  });
  phaseChips.appendChild(chip);
});

const tableSearch = document.getElementById('tableSearch');
const searchInput = document.getElementById('searchInput');
function currentQuery(){ return (tableSearch.value || searchInput.value || '').trim().toLowerCase(); }

function applyFilters(){
  const q = currentQuery();
  document.querySelectorAll('.elcell').forEach(cell=>{
    const e = byZ[cell.dataset.z];
    let matchesQ = true;
    if(q){
      matchesQ = e.name.toLowerCase().includes(q) || e.sym.toLowerCase().includes(q) || String(e.Z)===q;
    }
    const matchesCat = activeCats.size===0 || activeCats.has(e.cat);
    const matchesPhase = activePhases.size===0 || activePhases.has(e.phase);
    const match = matchesQ && matchesCat && matchesPhase;
    cell.classList.toggle('dimmed', !match);
    cell.classList.toggle('hit', match && (q!=='' ));
  });
}
tableSearch.addEventListener('input', applyFilters);
searchInput.addEventListener('input', ()=>{ tableSearch.value = searchInput.value; applyFilters(); });
document.getElementById('clearFiltersBtn').addEventListener('click', ()=>{
  activeCats.clear(); activePhases.clear();
  document.querySelectorAll('.filter-chip').forEach(c=>c.setAttribute('aria-pressed','false'));
  tableSearch.value=''; searchInput.value='';
  applyFilters();
});

//PANEL 
const panel = document.getElementById('panel');
const scrim = document.getElementById('scrim');
let lastFocused = null;

function shellSVG(shells){
  const cx=90, cy=90;
  let rings='', dots='';
  shells.forEach((count,i)=>{
    const r = 16 + i*15;
    rings += `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="var(--line-strong)" stroke-width="1"/>`;
    for(let k=0;k<count;k++){
      const ang = (2*Math.PI/count)*k - Math.PI/2;
      const ex = cx + r*Math.cos(ang), ey = cy + r*Math.sin(ang);
      dots += `<circle cx="${ex.toFixed(1)}" cy="${ey.toFixed(1)}" r="2.6" fill="var(--accent)"/>`;
    }
  });
  return `<svg width="180" height="180" viewBox="0 0 180 180">${rings}<circle cx="${cx}" cy="${cy}" r="7" fill="var(--accent-2)"/>${dots}</svg>`;
}

function panelHTML(e){
  const meta = CAT_META[e.cat]||{css:'--c-unknown'};
  const protons = e.Z, neutrons = Math.round(e.mass) - e.Z, electrons = e.Z;
  return `
    <div class="panel-head">
      <button class="icon-btn panel-close" id="panelCloseBtn" aria-label="Close panel">
        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M6 6l12 12M18 6 6 18"/></svg>
      </button>
      <div class="panel-badge"><span class="sw" style="background:var(${meta.css})"></span><span>${e.cat}</span></div>
      <div class="panel-title">
        <span class="z">${e.Z}</span>
        <span class="sym" id="panelName">${e.sym}</span>
        <span class="name">${e.name}</span>
      </div>
      <div class="panel-jump">
        <a href="#p-overview">Overview</a><a href="#p-props">Properties</a><a href="#p-shell">Structure</a><a href="#p-uses">Uses</a><a href="#p-disc">Discovery</a>
      </div>
    </div>
    <div class="panel-body">
      <div class="panel-section" id="p-overview">
        <h3>Overview</h3>
        <div class="panel-img">
          <img src="${e.imgUrl}" alt="${e.imgTitle||e.name}" loading="lazy" onerror="this.closest('.panel-img').style.display='none'">
        </div>
        <p class="img-credit">${e.imgAttr || ''}</p>
        <p class="panel-desc">${e.desc}</p>
        <h3 style="margin-top:4px;">Interesting facts</h3>
        <ul class="fact-list">${e.facts.map(f=>`<li>${f}</li>`).join('')}</ul>
      </div>

      <div class="panel-section" id="p-props">
        <h3>Basic information</h3>
        <div class="prop-grid">
          <div class="cell"><div class="k">Atomic mass</div><div class="v">${e.mass} u</div></div>
          <div class="cell"><div class="k">Group / Period</div><div class="v">${e.group ?? '—'} / ${e.period}</div></div>
          <div class="cell"><div class="k">Block</div><div class="v">${e.block}-block</div></div>
          <div class="cell"><div class="k">State (room temp)</div><div class="v">${e.phase}</div></div>
          <div class="cell"><div class="k">Protons</div><div class="v">${protons}</div></div>
          <div class="cell"><div class="k">Electrons</div><div class="v">${electrons}</div></div>
          <div class="cell"><div class="k">Neutrons (typical)</div><div class="v">${neutrons}</div></div>
          <div class="cell"><div class="k">Category</div><div class="v" style="font-size:.76rem;">${e.cat}</div></div>
        </div>
        <h3 style="margin-top:18px;">Physical & atomic properties</h3>
        <div class="prop-grid">
          <div class="cell"><div class="k">Melting point</div><div class="v">${e.melt!==null? e.melt+' °C':'—'}</div></div>
          <div class="cell"><div class="k">Boiling point</div><div class="v">${e.boil!==null? e.boil+' °C':'—'}</div></div>
          <div class="cell"><div class="k">Density</div><div class="v">${e.density!==null? e.density+' g/cm³':'—'}</div></div>
          <div class="cell"><div class="k">Electronegativity</div><div class="v">${e.eneg!==null? e.eneg+' (Pauling)':'—'}</div></div>
          <div class="cell"><div class="k">Ionization energy</div><div class="v">${e.ion1!==null? e.ion1+' kJ/mol':'—'}</div></div>
          <div class="cell"><div class="k">Electron affinity</div><div class="v">${e.ea!==null? e.ea+' kJ/mol':'—'}</div></div>
          <div class="cell"><div class="k">Oxidation states</div><div class="v" style="font-size:.76rem;">${e.oxid}</div></div>
          <div class="cell"><div class="k">Crystal structure</div><div class="v" style="font-size:.76rem;">${e.crystal}</div></div>
        </div>
      </div>

      <div class="panel-section" id="p-shell">
        <h3>Electron configuration</h3>
        <div class="econf-display">${e.econfShort}</div>
        <div class="shell-wrap" style="margin-top:14px;">
          ${shellSVG(e.shells)}
          <div style="font-size:.82rem; color:var(--ink-soft);">
            Shells (inner → outer):<br><b style="font-family:var(--font-mono); color:var(--ink);">${e.shells.join(' · ')}</b>
          </div>
        </div>
      </div>

      <div class="panel-section" id="p-uses">
        <h3>Uses & applications</h3>
        <div class="chip-row">${e.uses.map(u=>`<span class="chip">${u}</span>`).join('')}</div>
      </div>

      <div class="panel-section" id="p-disc">
        <h3>Discovery</h3>
        <dl class="disc-card">
          <dt>Discovered by</dt><dd>${e.discoverer}</dd>
          <dt>Year</dt><dd>${e.year}</dd>
          <dt>Name origin</dt><dd>${e.etym}</dd>
        </dl>
      </div>
    </div>
  `;
}

function openPanel(z){
  lastFocused = document.activeElement;
  const e = byZ[z];
  panel.innerHTML = panelHTML(e);
  panel.classList.add('open'); scrim.classList.add('open');
  document.body.style.overflow='hidden';
  document.getElementById('panelCloseBtn').addEventListener('click', closePanel);
  panel.focus();
}
function closePanel(){
  panel.classList.remove('open'); scrim.classList.remove('open');
  document.body.style.overflow='';
  if(lastFocused) lastFocused.focus();
}
scrim.addEventListener('click', closePanel);
document.addEventListener('keydown', ev=>{ if(ev.key==='Escape') closePanel(); });

