//QUIZ 
const quizPanel = document.getElementById('quizPanel');
let quizState = {i:0, score:0, questions:[]};

function buildQuizQuestions(n=10){
  const pool = [...ELEMENTS];
  const qs = [];
  const types = ['symbolToName','numberToName','nameToSymbol','categoryOf'];
  for(let i=0;i<n;i++){
    const type = types[Math.floor(Math.random()*types.length)];
    const idx = Math.floor(Math.random()*pool.length);
    const target = pool[idx];
    let others = ELEMENTS.filter(e=>e.Z!==target.Z);
    others = others.sort(()=>Math.random()-0.5).slice(0,3);
    let prompt, correct, options;
    if(type==='symbolToName'){
      prompt = `Which element has the symbol "${target.sym}"?`;
      correct = target.name;
      options = [target.name, ...others.map(o=>o.name)];
    } else if(type==='numberToName'){
      prompt = `Which element has atomic number ${target.Z}?`;
      correct = target.name;
      options = [target.name, ...others.map(o=>o.name)];
    } else if(type==='nameToSymbol'){
      prompt = `What is the chemical symbol for ${target.name}?`;
      correct = target.sym;
      options = [target.sym, ...others.map(o=>o.sym)];
    } else {
      prompt = `${target.name} (${target.sym}) belongs to which category?`;
      correct = target.cat;
      const catPool = Object.keys(CAT_META).filter(c=>c!==target.cat).sort(()=>Math.random()-0.5).slice(0,3);
      options = [target.cat, ...catPool];
    }
    options = options.sort(()=>Math.random()-0.5);
    qs.push({prompt, correct, options});
  }
  return qs;
}

function renderQuiz(){
  if(quizState.i >= quizState.questions.length){
    quizPanel.innerHTML = `
      <p class="quiz-progress">Complete</p>
      <h3 class="quiz-q">You scored <span class="quiz-score">${quizState.score} / ${quizState.questions.length}</span></h3>
      <button class="btn btn-primary" id="quizRestart">Play again</button>
    `;
    document.getElementById('quizRestart').addEventListener('click', startQuiz);
    return;
  }
  const q = quizState.questions[quizState.i];
  quizPanel.innerHTML = `
    <p class="quiz-progress">Question ${quizState.i+1} of ${quizState.questions.length} · Score ${quizState.score}</p>
    <h3 class="quiz-q">${q.prompt}</h3>
    <div class="quiz-opts">${q.options.map(o=>`<button class="quiz-opt" data-v="${o}">${o}</button>`).join('')}</div>
    <div class="quiz-feedback" id="quizFeedback"></div>
  `;
  quizPanel.querySelectorAll('.quiz-opt').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      quizPanel.querySelectorAll('.quiz-opt').forEach(b=>b.disabled=true);
      const chosen = btn.dataset.v;
      const feedback = document.getElementById('quizFeedback');
      if(chosen === q.correct){
        btn.classList.add('correct'); quizState.score++;
        feedback.textContent = 'Correct!';
      } else {
        btn.classList.add('wrong');
        feedback.textContent = `Not quite — the answer was ${q.correct}.`;
        quizPanel.querySelectorAll('.quiz-opt').forEach(b=>{ if(b.dataset.v===q.correct) b.classList.add('correct'); });
      }
      setTimeout(()=>{ quizState.i++; renderQuiz(); }, 1100);
    });
  });
}
function startQuiz(){
  quizState = {i:0, score:0, questions: buildQuizQuestions(10)};
  renderQuiz();
}
startQuiz();
